interface Comment { id: string; body: string; createdAt: Date }
type CommentDTO = { id: string; body: string; createdAt: Date };

async function listComments(threadId: string): Promise<Comment[]> {
  const rows = await dbQuery('select * from comments where thread_id = $1', [threadId]);
  return rows as Comment[];
}

function toDTO(c: Comment): CommentDTO {
  return { id: c.id, body: c.body, createdAt: c.createdAt };
}
